"""Pure renderer for the generated Onion Sentinel dashboard shell."""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class DashboardShellViewModel:
    navigation_html: str
    overview_html: str
    metrics_html: str
    alert_table_html: str
    generated_at: str
    database_path: str
    source_directory: str
    adjudication_modal_html: str


